import { Keyboard } from 'react-native';
import { NavigationService } from '../services/NavigationService';
import { SCREENS_ENUM } from '../types/global';
import { logger } from '../utils';

export interface FormForgotPassword {
  email: string;
}

export const handleSubmit = (values: FormForgotPassword) => {
  try {
    Keyboard.dismiss();
    const { email } = values;
    if (!email) {
      return;
    }
    NavigationService.navigate(SCREENS_ENUM.ChangePasswordScreen, { email });
  } catch (error) {
    logger('error handleSubmit', error);
  }
};
